import { fireEvent, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { McpToolExecutedEventInfo } from "./McpToolExecutedEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({
    title,
    onClose,
    children,
  }: {
    title: string;
    onClose: () => void;
    children: React.ReactNode;
  }) => (
    <div>
      <h1>{title}</h1>
      <button data-testid="event-details-close" onClick={onClose}>
        Close
      </button>
      {children}
    </div>
  ),
}));

const baseEvent: ConversationEvent = {
  __typename: "ConversationEvent",
  id: "1",
  conversationEventType: ConversationEventType.McpToolExecuted,
  name: "event_name",
  actionText: "",
  flowId: "",
  slotValue: null,
  stepId: "",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  metadata: {
    tool_name: "my_tool",
    tool_arguments: { query: "hello" },
    tool_result: "some result",
    tool_is_error: false,
    tool_source: "mcp",
    parseData: {},
  },
};

describe("McpToolExecutedEventInfo", () => {
  it("renders the CALM title", () => {
    renderWithProviders(<McpToolExecutedEventInfo event={baseEvent} onClose={vi.fn()} />);

    expect(screen.getByText("MCP tool executed")).toBeInTheDocument();
    expect(screen.queryByText("Tool executed")).not.toBeInTheDocument();
  });

  it("calls onClose when close button is clicked", () => {
    const onClose = vi.fn();
    renderWithProviders(<McpToolExecutedEventInfo event={baseEvent} onClose={onClose} />);

    fireEvent.click(screen.getByTestId("event-details-close"));
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("does not show Source even when metadata stamps tool_source mcp", () => {
    renderWithProviders(<McpToolExecutedEventInfo event={baseEvent} onClose={vi.fn()} />);

    expect(screen.queryByText("Source")).not.toBeInTheDocument();
  });

  it("shows Server when mcp_server is set", () => {
    const event: ConversationEvent = {
      ...baseEvent,
      metadata: {
        ...baseEvent.metadata,
        tool_mcp_server: "payments",
      },
    };

    renderWithProviders(<McpToolExecutedEventInfo event={event} onClose={vi.fn()} />);

    expect(screen.getByText("Server")).toBeInTheDocument();
    expect(screen.getByText("payments")).toBeInTheDocument();
    expect(screen.queryByText("Source")).not.toBeInTheDocument();
  });
});
